@startuml

class Client {
  + NIN : string
  + TIN : string
  + name : string
  + address : string
}

class BicycleModel {
  + name : string
  + gears : int
}

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Bicycle {
  + id : string
}

class Store {
  + name : string
  + address : string
}

class Reservation {
  + pickupDate : date
}

class Rental {
  + returnDate : date
}

BicycleModel "1" -- "*" Bicycle : is model of
BicycleModel "1" -- "*" Reservation : requested in
Client "1" -- "*" Reservation : makes
Store "1" -- "*" Reservation : pickup location
Reservation "1" -- "0..1" Rental : becomes
Rental "1" -- "1" Bicycle : involves
Rental "1" -- "1" Store : return location

@enduml

